// keyBinding(): parity with the peck.to v1 client, admission by the overlay's
// rule, and the read that tells a writer whether a binding is needed.
//
// The v1 fixture holds the key-binding scripts v1's `bootstrapIdentity`
// produces; it is generated by running v1's own code (see
// scripts/gen-v1-key-binding-fixtures.mjs), not written by hand. The builder
// must reproduce every script byte for byte, both signatures included: the
// wallet is a ProtoWallet with the same fixed key, and ECDSA here is
// deterministic.
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { LockingScript, PrivateKey, ProtoWallet, PublicKey, Utils, type WalletInterface } from '@bsv/sdk'
import { describe, expect, it } from 'vitest'
import {
  KEY_BINDING_NO_REVOCATION,
  PROTO_MAP,
  SchemaError,
  keyBinding,
  keyBindingPreimage,
  opReturnPushes,
  post,
  signPayload,
  toLockingScript,
  verifyAip,
  verifyKeyBinding,
} from '../src/schema/index.js'
import { OVERLAY_TOPICS, OverlaySubmitError, hasKeyBinding, signingKeys } from '../src/submit/index.js'
import { firstWriteTx } from './helpers/key-binding-tx.js'
import { overlayAdmit, overlayIsValidBinding, overlayMapFields, overlaySigningKeyRow } from './helpers/overlay-key-binding.js'

interface Fixture {
  v1Rev: string | null
  bindings: Array<{ note: string; walletKey: number; serial: string; identityKey: string; subjectKey: string; scriptHex: string }>
}

const fixture = JSON.parse(
  readFileSync(resolve(import.meta.dirname, 'fixtures/schema/v1-key-binding.json'), 'utf8'),
) as Fixture

const LOGIN = { protocolID: [1, 'identity'] as [1, string], keyID: '1', counterparty: 'self' }

async function loginKey(wallet: ProtoWallet): Promise<string> {
  return (await wallet.getPublicKey(LOGIN)).publicKey
}

/** Rebuild an OP_RETURN MAP script with some fields replaced (to forge records). */
function withFields(scriptHex: string, change: Record<string, string>): string {
  const t = opReturnPushes(scriptHex)!.map((b) => Utils.toUTF8(b))
  const out = t.slice(0, 2)
  for (let i = 2; i + 1 < t.length; i += 2) out.push(t[i]!, change[t[i]!] ?? t[i + 1]!)
  return toLockingScript({ pushes: out.map((s) => Utils.toArray(s, 'utf8')) }).toHex()
}

describe('fixture', () => {
  it('is generated from v1 and covers more than one wallet', () => {
    expect(fixture.bindings.length).toBeGreaterThanOrEqual(2)
    expect(new Set(fixture.bindings.map((b) => b.identityKey)).size).toBe(fixture.bindings.length)
  })
})

describe('keyBinding(): the same bytes as the v1 bootstrapIdentity binding', () => {
  for (const c of fixture.bindings) {
    it(c.note, async () => {
      const wallet = new ProtoWallet(new PrivateKey(c.walletKey))
      const binding = await keyBinding({ serial: c.serial }, { wallet })
      expect(toLockingScript(binding).toHex()).toBe(c.scriptHex)
      expect(binding.certifier).toBe(c.identityKey)
      expect(binding.subject).toBe(c.subjectKey)
      // The subject is the login key: the key v1 and v2 AIP-sign posts with.
      expect(binding.subject).toBe(await loginKey(wallet))
      expect(binding.signingAddress).toBe(PublicKey.fromString(c.subjectKey).toAddress())
    })
  }

  it('lays out MAP SET and the fields in v1 order, sig then subjectsig last', () => {
    const c = fixture.bindings[0]!
    const texts = opReturnPushes(c.scriptHex)!.map((b) => Utils.toUTF8(b))
    expect(texts.filter((_, i) => i < 2 || i % 2 === 0)).toEqual([
      PROTO_MAP, 'SET', 'app', 'type', 'schema_version', 'subject', 'certifier', 'serial', 'purpose', 'revocation', 'sig', 'subjectsig',
    ])
    expect(texts.slice(2, 8)).toEqual(['app', 'overlay.social', 'type', 'keybinding', 'schema_version', '1'])
    expect(texts[texts.indexOf('revocation') + 1]).toBe(KEY_BINDING_NO_REVOCATION)
    // No `|` and no AIP section: the two signatures are the record's own.
    expect(texts).not.toContain('|')
  })

  it('signs the canonical preimage: sorted-key JSON of every field but the two signatures', async () => {
    const c = fixture.bindings[0]!
    const check = verifyKeyBinding(c.scriptHex)!
    const json = Utils.toUTF8(keyBindingPreimage(check.fields))
    expect(json.startsWith('{"app":"overlay.social","certifier":"')).toBe(true)
    expect(json).not.toContain('"sig"')
    expect(json).not.toContain('subjectsig')
    expect(Object.keys(JSON.parse(json))).toEqual(['app', 'certifier', 'purpose', 'revocation', 'schema_version', 'serial', 'subject', 'type'])
  })

  it('draws a fresh 8-byte serial when none is given', async () => {
    const wallet = new ProtoWallet(new PrivateKey(20261006))
    const a = await keyBinding({}, { wallet })
    const b = await keyBinding({}, { wallet })
    expect(a.fields.serial).toMatch(/^[0-9a-f]{16}$/)
    expect(a.fields.serial).not.toBe(b.fields.serial)
    expect(verifyKeyBinding(toLockingScript(a))?.valid).toBe(true)
  })

  it('writes boundAt, a custom purpose and revocation when given, and still verifies', async () => {
    const wallet = new ProtoWallet(new PrivateKey(5))
    const binding = await keyBinding(
      { serial: '0123456789abcdef', boundAt: '1760000000', purpose: 'chat', revocation: `${'ab'.repeat(32)}.3` },
      { wallet },
    )
    const texts = opReturnPushes(toLockingScript(binding))!.map((b) => Utils.toUTF8(b))
    expect(texts.indexOf('boundAt')).toBe(texts.indexOf('revocation') + 2)
    expect(binding.fields.purpose).toBe('chat')
    expect(await overlayIsValidBinding({ ...binding.fields })).toBe(true)
  })

  it('refuses bad input before asking the wallet', async () => {
    const wallet = new ProtoWallet(new PrivateKey(5))
    await expect(keyBinding({ serial: 'XYZ' }, { wallet })).rejects.toThrow(SchemaError)
    await expect(keyBinding({ revocation: 'nope' }, { wallet })).rejects.toThrow(SchemaError)
    await expect(keyBinding({ boundAt: '-1' }, { wallet })).rejects.toThrow(SchemaError)
  })
})

describe('the overlay admits it (port of the tm_key-binding topic manager and lookup service)', () => {
  for (const c of fixture.bindings) {
    it(`admits v1's own script: ${c.note}`, async () => {
      expect(await overlayIsValidBinding(overlayMapFields(c.scriptHex)!)).toBe(true)
    })
  }

  it('admits the binding next to a post in one transaction, and indexes the post\'s signing address to the identity', async () => {
    const wallet = new ProtoWallet(new PrivateKey(20261006))
    const postScript = await signPayload(post({ app: 'peck.to', text: 'first post' }), { wallet })
    const binding = await keyBinding({}, { wallet })
    const tx = firstWriteTx([postScript, toLockingScript(binding)])

    // tm_key-binding takes output 1 only; the post is tm_social-content's.
    expect(await overlayAdmit(tx.toBEEF())).toEqual([1])

    const row = await overlaySigningKeyRow(tx.toAtomicBEEF(), 1)
    const identity = (await wallet.getPublicKey({ identityKey: true })).publicKey
    // The post's AIP signer address is exactly the row's signing_address: what
    // the indexer's identityOwnsAddress(identity, address) looks up.
    const aip = verifyAip(postScript)!
    expect(aip.valid).toBe(true)
    expect(row).toMatchObject({
      signing_pubkey: aip.signer.toLowerCase(),
      signing_address: PublicKey.fromString(aip.signer).toAddress(),
      identity_subject: identity,
      binding_outpoint: `${tx.id('hex')}.1`,
      revocation_outpoint: KEY_BINDING_NO_REVOCATION,
      spent: false,
    })
  })

  it('verifyKeyBinding() agrees with the overlay on every fixture', () => {
    for (const c of fixture.bindings) {
      expect(verifyKeyBinding(c.scriptHex)).toMatchObject({ subject: c.subjectKey, certifier: c.identityKey, valid: true })
    }
  })
})

describe('forged or broken bindings are refused', () => {
  const c = fixture.bindings[0]!
  const other = new ProtoWallet(new PrivateKey(31337))

  async function refused(scriptHex: string) {
    const tx = firstWriteTx([LockingScript.fromHex(scriptHex)])
    expect(await overlayAdmit(tx.toBEEF())).toEqual([])
    expect(await overlaySigningKeyRow(tx.toAtomicBEEF(), 0)).toBeNull()
    expect(verifyKeyBinding(scriptHex)?.valid).toBe(false)
  }

  it('a subjectsig by another key (binding a key you do not control)', async () => {
    const f = verifyKeyBinding(c.scriptHex)!.fields
    const { signature } = await other.createSignature({ data: keyBindingPreimage(f), ...LOGIN })
    await refused(withFields(c.scriptHex, { subjectsig: Utils.toHex(signature) }))
  })

  it('a subject swapped for someone else\'s key, signatures kept', async () => {
    await refused(withFields(c.scriptHex, { subject: await loginKey(other) }))
  })

  it('a certifier swapped for another identity (claiming someone else\'s key)', async () => {
    const otherIdentity = (await other.getPublicKey({ identityKey: true })).publicKey
    await refused(withFields(c.scriptHex, { certifier: otherIdentity }))
  })

  it('sig and subjectsig swapped', async () => {
    const f = verifyKeyBinding(c.scriptHex)!.fields
    await refused(withFields(c.scriptHex, { sig: f.subjectsig!, subjectsig: f.sig! }))
  })

  it('any signed field changed (purpose)', async () => {
    await refused(withFields(c.scriptHex, { purpose: 'something-else' }))
  })

  it('a subject equal to the certifier', async () => {
    await refused(withFields(c.scriptHex, { subject: c.identityKey }))
  })

  it('keyBinding() throws when the wallet signs with another key than it reported', async () => {
    const real = new ProtoWallet(new PrivateKey(20261006))
    const liar: Pick<WalletInterface, 'getPublicKey' | 'createSignature'> = {
      getPublicKey: (a) => real.getPublicKey(a),
      createSignature: (a) => (a.protocolID[1] === 'identity' ? other.createSignature(a) : real.createSignature(a)),
    }
    await expect(keyBinding({ serial: c.serial }, { wallet: liar })).rejects.toThrow(/do not verify/)
  })
})

describe('hasKeyBinding() / signingKeys()', () => {
  const identity = fixture.bindings[0]!.identityKey
  const subject = fixture.bindings[0]!.subjectKey
  const address = PublicKey.fromString(subject).toAddress()
  const answer = (body: unknown, status = 200) => async (url: RequestInfo | URL) => {
    calls.push(String(url))
    return new Response(JSON.stringify(body), { status, headers: { 'content-type': 'application/json' } })
  }
  let calls: string[] = []
  const bound = {
    status: 'ok',
    identity_subject: identity,
    count: 1,
    signingKeys: [{ pubkey: subject, address, boundAt: null, bindingOutpoint: `${'cd'.repeat(32)}.1`, revocationOutpoint: KEY_BINDING_NO_REVOCATION }],
  }

  it('asks GET /identity/<identity key>/signing-keys on the overlay', async () => {
    calls = []
    const keys = await signingKeys(identity.toUpperCase(), { fetch: answer(bound) as typeof fetch, overlayUrl: 'https://o.example/' })
    expect(calls).toEqual([`https://o.example/identity/${identity}/signing-keys`])
    expect(keys).toEqual([{ pubkey: subject, address, boundAt: null, bindingOutpoint: `${'cd'.repeat(32)}.1` }])
  })

  it('is true for the bound address or public key, false for another', async () => {
    const f = answer(bound) as typeof fetch
    expect(await hasKeyBinding(identity, address, { fetch: f })).toBe(true)
    expect(await hasKeyBinding(identity, subject, { fetch: f })).toBe(true)
    expect(await hasKeyBinding(identity, '1BoatSLRHtKNngkdXEeobR76b53LETtpyT', { fetch: f })).toBe(false)
    expect(await hasKeyBinding(identity, address, { fetch: answer({ ...bound, count: 0, signingKeys: [] }) as typeof fetch })).toBe(false)
  })

  it('rejects, never answers false, when the overlay cannot say', async () => {
    await expect(hasKeyBinding(identity, address, { fetch: answer({ error: 'x' }, 500) as typeof fetch })).rejects.toMatchObject({ code: 'server' })
    await expect(hasKeyBinding(identity, address, { fetch: answer({ nope: 1 }) as typeof fetch })).rejects.toMatchObject({ code: 'invalid_response' })
    await expect(hasKeyBinding(identity, address, { fetch: (async () => { throw new TypeError('offline') }) as typeof fetch })).rejects.toMatchObject({ code: 'network' })
    await expect(hasKeyBinding('nope', address)).rejects.toBeInstanceOf(OverlaySubmitError)
  })

  it('the topic to submit a binding to', () => {
    expect(OVERLAY_TOPICS.keyBinding).toBe('tm_key-binding')
  })
})
